import assert from 'node:assert/strict';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, realpathSync, rmSync, symlinkSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { runBenchCli } from './history-only-reword-6qjyzwas/tree/scripts/mikro/bench';
import { runAgent } from './history-only-reword-6qjyzwas/tree/scripts/mikro/call';
import { runFixturesCli } from './history-only-reword-6qjyzwas/tree/scripts/mikro/fixtures-from-commits';

// Standalone non-test program. Real runAgent stops in its injectable execution-boundary opener,
// after the production configuration trust gate but before runtime/provider execution.
assert.equal(process.env.HOME, '/home/genie/.local/share/mikro-engine-split/experiments-g8/final-local-smokes/g5-private-home');
assert.equal(Object.keys(process.env).some(k => /KEY|TOKEN|SECRET|CREDENTIAL/.test(k)), false);
const root = mkdtempSync('/home/genie/.local/share/mikro-engine-split/experiments-g8/final-local-smokes/g5-alias-proof-');
const write = (dir: string, path: string, value: string) => { mkdirSync(dirname(join(dir,path)), {recursive:true}); writeFileSync(join(dir,path),value); };
const git = (dir: string, ...args: string[]) => {
  const result = Bun.spawnSync(['/usr/bin/git','-C',dir,'-c','user.name=Local Smoke','-c','user.email=smoke@invalid',...args]);
  assert.equal(result.exitCode,0,result.stderr.toString()); return result.stdout.toString().trim();
};
const physicalTmp = join(root,'physical-tmp'); mkdirSync(physicalTmp);
const tmpAlias = join(root,'tmp-alias'); symlinkSync(physicalTmp,tmpAlias,'dir'); process.env.TMPDIR = tmpAlias;
let boundaryCalls=0;
const marker = new Error('G5_LOCAL_MARKER_BEFORE_INFERENCE');
const setup = (name: string) => { const dir=join(root,name);mkdirSync(dir);git(dir,'init','-q','-b','main');return dir; };
const config = 'model: { provider: deepseek, model: deepseek-flash }\n';
const prompt = (dir: string) => { write(dir,'.mikro/agents/wish-context/agent.yaml','model: deepseek/deepseek-flash\nsystem: SYSTEM.md\n');write(dir,'.mikro/agents/wish-context/SYSTEM.md','# trusted local prompt\n'); };
const alias = (dir: string,name: string) => {const path=join(root,name);symlinkSync(dir,path,'dir');return path;};
const args = (dir: string, runtimeAlias: string) => ['wish-context','--dir',dir,'--agents-dir',join(runtimeAlias,'.mikro/agents'),'--boundary','bwrap','--concurrency','1','--reps','1','--no-phoenix'];
const clean = (dir: string, before: string) => {assert.equal(git(dir,'worktree','list','--porcelain'),before);assert.equal(readdirSync(physicalTmp).some(p=>p.startsWith('mikro-fixture-')),false);};
const dir=setup('historical-repository');
write(dir,'src/base.ts','export const base = 1;\n');write(dir,'.mikro/mikro.yaml','model: { provider: deepseek-api, model: deepseek-flash }\n');write(dir,'.mikro/TOOLS.md','# historical tools\n');git(dir,'add','-A');git(dir,'commit','-qm','base');const parent=git(dir,'rev-parse','HEAD');
write(dir,'src/nested/implementation.ts','export const implemented = true;\n');git(dir,'add','-A');git(dir,'commit','-qm','feat: nested implementation');const source=git(dir,'rev-parse','HEAD');
assert.equal(runFixturesCli(['--from-commits','HEAD^..HEAD','--agent','wish-context','--dir',dir]),0);
const fixturePath=join(dir,'.mikro/fixtures/wish-context.json');const fixtures=JSON.parse(readFileSync(fixturePath,'utf8'));const fixture=fixtures.fixtures[0];
assert.equal(fixture.sourceCommit,source);assert.equal(fixture.parentCommit,parent);assert.equal(fixture.evaluationCommit,parent);assert.deepEqual(fixture.truth.newFiles,['src/nested/implementation.ts']);
write(dir,'.mikro/mikro.yaml',config);rmSync(join(dir,'.mikro/TOOLS.md'));prompt(dir);const runtimeAlias=alias(dir,'runtime-alias');const before=git(dir,'worktree','list','--porcelain');let evaluationDir='';
const runner: typeof runAgent = options => {
  assert.equal(options.agentsDir,join(runtimeAlias,'.mikro/agents'));
  return runAgent({...options,ledger:false,phoenix:false,openBoundary:async request=>{
    boundaryCalls++;evaluationDir=request.dir;
    assert.equal(git(request.dir,'rev-parse','HEAD'),parent);
    assert.equal(realpathSync(request.dir),request.dir);
    assert.ok(request.dir.startsWith(physicalTmp+'/mikro-fixture-'));
    assert.equal(readFileSync(join(request.dir,'.mikro/mikro.yaml'),'utf8'),config);
    assert.equal(existsSync(join(request.dir,'.mikro/TOOLS.md')),false);
    assert.equal(existsSync(join(request.dir,'src/nested/implementation.ts')),false);
    assert.equal(readFileSync(join(request.dir,'src/base.ts'),'utf8'),'export const base = 1;\n');
    throw marker;
  }});
};
await assert.rejects(runBenchCli(args(dir,runtimeAlias),runner),error=>error===marker);
assert.equal(boundaryCalls,1);assert.equal(existsSync(evaluationDir),false);clean(dir,before);
console.log(JSON.stringify({scenario:'aliased-runtime-and-TMPDIR',marker:marker.message,boundaryCalls,sourceCommit:source,parentCommit:parent,evaluationCommit:fixture.evaluationCommit,newFiles:fixture.truth.newFiles,lexicalAgentsDir:join(runtimeAlias,'.mikro/agents'),evaluationDir,worktreeCleanup:true}));
for(const owner of ['source','historical']) for(const component of ['file','directory']) {
  const repo=setup(`${owner}-${component}`);const outside=join(root,`${owner}-${component}-outside`);write(outside,'mikro.yaml',config);
  const link=()=>{if(component==='directory'){rmSync(join(repo,'.mikro'),{recursive:true,force:true});symlinkSync(outside,join(repo,'.mikro'),'dir');}else{mkdirSync(join(repo,'.mikro'),{recursive:true});rmSync(join(repo,'.mikro/mikro.yaml'),{force:true});symlinkSync(join(outside,'mikro.yaml'),join(repo,'.mikro/mikro.yaml'));}};
  write(repo,'src/base.ts','base\n');if(owner==='historical')link();git(repo,'add','-A');git(repo,'commit','-qm','base');const commit=git(repo,'rev-parse','HEAD');
  rmSync(join(repo,'.mikro'),{recursive:true,force:true});write(repo,'.mikro/mikro.yaml',config);if(owner==='source')link();prompt(repo);
  write(repo,'.mikro/fixtures/wish-context.json',JSON.stringify({fixtures:[{id:`${owner}-${component}`,prompt:'Intent: add module',evaluationCommit:commit,truth:{newFiles:['src/new.ts']}}]}));
  const aliased=alias(repo,`${owner}-${component}-alias`);const list=git(repo,'worktree','list','--porcelain');let calls=0;
  const realRunner: typeof runAgent=options=>{calls++;return runAgent({...options,ledger:false,phoenix:false,openBoundary:async()=>{boundaryCalls++;throw marker;}});};
  await assert.rejects(runBenchCli(args(repo,aliased),realRunner),/runtime configuration has a symlink component/);assert.equal(calls,0);clean(repo,list);assert.equal(readFileSync(join(outside,'mikro.yaml'),'utf8'),config);
  console.log(JSON.stringify({scenario:`reject-${owner}-config-${component}-symlink`,runnerCalls:calls,worktreeCleanup:true,outsideBytesUnchanged:true}));
}
const overlap=JSON.parse(JSON.stringify(fixtures));overlap.fixtures[0].truth.newFiles=['.mikro/mikro.yaml'];write(dir,'overlap.json',JSON.stringify(overlap));let overlapCalls=0;
await assert.rejects(runBenchCli([...args(dir,runtimeAlias),'--fixtures',join(dir,'overlap.json')],options=>{overlapCalls++;return runner(options);}),/truth overlaps runtime configuration/);assert.equal(overlapCalls,0);clean(dir,before);
console.log(JSON.stringify({scenario:'NEW-runtime-overlap-refused',runnerCalls:overlapCalls,worktreeCleanup:true}));
assert.equal(boundaryCalls,1);
console.log(JSON.stringify({proofRoot:root,externalModelProviderCalls:0,realRunAgentBoundaryCalls:boundaryCalls,limit:'intentional marker before inference; no benchmark output, grading, resampling, or full containment execution claimed',exit:0}));
